+package cmd
+
+import "testing"
+
+func TestResolveListenerHosts(t *testing.T) {
+       tester := func(t *testing.T, host, managementHost, mitmHost, wantManagementHost, wantMITMHost string) {
+               t.Helper()
+
+               managementHost, mitmHost = resolveListenerHosts(host, managementHost, mitmHost)
+               if managementHost != wantManagementHost {
+                       t.Errorf("management host = %q, want %q", managementHost, wantManagementHost)
+               }
+               if mitmHost != wantMITMHost {
+                       t.Errorf("MITM host = %q, want %q", mitmHost, wantMITMHost)
+               }
+       }
+
+       t.Run("uses the legacy host for both listeners by default", func(t *testing.T) {
+               tester(t, "127.0.0.1", "", "", "127.0.0.1", "127.0.0.1")
+       })
+       t.Run("allows the management listener to override the legacy host", func(t *testing.T) {
+               tester(t, "127.0.0.1", "172.30.20.2", "", "172.30.20.2", "127.0.0.1")
+       })
+       t.Run("allows the MITM listener to override the legacy host", func(t *testing.T) {
+               tester(t, "127.0.0.1", "", "172.30.10.2", "127.0.0.1", "172.30.10.2")
+       })
+       t.Run("allows both listeners to use distinct network addresses", func(t *testing.T) {
+               tester(t, "127.0.0.1", "172.30.20.2", "172.30.10.2", "172.30.20.2", "172.30.10.2")
